UPDATE column_info
column_name = #{columnName}, column_description = #{columnDescription}, semantic_type = #{semanticType}, is_visible = #{isVisible}, update_time = #{updateTime},
WHERE id = #{id}

UPDATE column_info
column_name = #{columnName}, physical_column_description = #{physicalColumnDescription}, column_description = COALESCE(NULLIF(column_description, ''), #{columnDescription}), type_name = #{typeName}, primary_key = #{primaryKey}, index_info = #{indexInfo}, physical_status = #{physicalStatus}, update_time = #{updateTime},
WHERE id = #{id}

UPDATE column_info
SET physical_status = 0,
    update_time = #{now}
WHERE id IN

    #{id}

  AND (physical_status IS NULL OR physical_status <> 0)
